/** A pasted credential is write-only. The name, never its URL, is the browser's saved view. */
export async function addWebhookChannel(input: unknown): Promise<Result<{ id: string }>> {
  const member = await begin("channels:manage");
  if (!isMember(member)) return member;
  const parsed = channelInput.safeParse(input);
  if (!parsed.success) return { ok: false, reason: "Check the channel details.", fieldErrors: Object.fromEntries(parsed.error.issues.map((i) => [String(i.path[0]), i.message])) };
  const v = parsed.data;
  const over = await spend(member, "alert_confirm");
  if (over) return over;
  if (v.kind === "webhook") {
    const checked = await checkTarget(new URL(v.url).hostname.replace(/^\[|\]$/g, ""));
    if (!checked.ok) return { ok: false, reason: "The webhook must resolve only to public addresses. Check the address and try again." };
  }
  const id = `chan_${randomBytes(12).toString("hex")}`;
  const credential = v.kind === "discord" ? { url: discordUrl(v.url)!.href } : { url: v.url, secret: v.secret };
  const { error } = await db().from("alert_channels").insert({ id, workspace_id: member.workspace.id,
    kind: v.kind, label: v.label, sealed: seal(JSON.stringify(credential), channelContext(member.workspace.id, id)),
    confirmed_at: new Date().toISOString(), created_by: member.caller.userId });
  if (error) return refused(error, member);
  return { ok: true, id };
}

export async function connectSlack(): Promise<Result<{ url: string }>> {
  const member = await begin("channels:manage");
  if (!isMember(member)) return member;
  const e = env();
    if (d.why || !d.channel) return skip(d, SKIPPED[d.why ?? "channel_removed"]);
    if (d.channel.kind === "telegram") return deliverTelegram(d, d.channel);
    if (d.channel.kind === "email") return deliverEmail(d, d.channel);
    if (deps.channels && ["slack", "discord", "webhook"].includes(d.channel.kind)) {
      if (!d.channel.sealed) return fail(d, "This channel has no credential. Remove it and add it again.");
      let credential: { token?: string; channel?: string; url?: string; secret?: string };
      try {
        credential = z.object({ token: z.string().optional(), channel: z.string().optional(), url: z.string().optional(), secret: z.string().optional() })
          .parse(JSON.parse(open(d.channel.sealed, channelContext(d.workspaceId, d.channel.id), deps.channels.key)));
      } catch { return fail(d, "This channel's credential could not be opened."); }
      const message = messageFor(d, deps.appUrl, null, now());
      if (!message) return skip(d, "What it was about is gone.");
      if (d.channel.kind === "slack") {
        if (!credential.token || !credential.channel) return fail(d, "Slack needs to be connected again.");
        if (d.event === "resolved" && !d.parentProviderId) return skip(d, "The opening message wasn't confirmed, so no thread reply was sent.");
        return settle(d, await sendSlack(credential.token, credential.channel, message, d.event === "resolved" ? d.parentProviderId! : null, deps.channels.fetch));
      }
      if (d.channel.kind === "discord") return settle(d, await sendDiscord(credential.url ?? "", message, deps.channels.fetch));
      if (!credential.url || !credential.secret) return fail(d, "The webhook needs to be added again.");
      if ((d.webhookAttempts ?? 0) >= 6) return fail(d, "The webhook exhausted its five retries.");
      const prepared = await deps.rpc("alert_prepare_webhook", { p_id: d.id, p_claim: claimId, p_body: webhookPayload(d, deps.appUrl) });
import { z } from "zod";
import { ipVersion, isLocalName, isPublicIp } from "../ip";

/** URLs are credentials; validation errors never echo any portion of one. */
export function webhookUrl(value: string): URL | null {
  try {
    const u = new URL(value);
    const host = u.hostname.replace(/^\[|\]$/g, "");
    if (u.protocol !== "https:" || u.username || u.password || u.hash || (u.port && u.port !== "443") ||
        isLocalName(host) || (ipVersion(host) && !isPublicIp(host))) return null;
    return u;
  } catch { return null; }
}

export function discordUrl(value: string): URL | null {
  const u = webhookUrl(value);
  if (!u || !["discord.com", "discordapp.com"].includes(u.hostname) || u.search ||
      !/^\/api(?:\/v10)?\/webhooks\/\d{17,22}\/[A-Za-z0-9_-]{40,150}$/.test(u.pathname)) return null;
  u.hostname = "discord.com";
  return u;
}

export const channelInput = z.object({
  kind: z.enum(["discord", "webhook"]),
  label: z.string().trim().min(1, "Give this channel a name.").max(120),
  url: z.string().trim().max(2048),
  // Supplied by the receiver's owner, never returned after save.
  secret: z.string().max(256).optional(),
}).superRefine((v, ctx) => {
  if (!(v.kind === "discord" ? discordUrl(v.url) : webhookUrl(v.url)))
    ctx.addIssue({ code: "custom", path: ["url"], message: v.kind === "discord" ? "Paste a Discord channel webhook URL." : "Use a public HTTPS address on port 443, without a login or fragment." });
  if (v.kind === "webhook" && (!v.secret || !/^[A-Za-z0-9_-]{32,256}$/.test(v.secret)))
    ctx.addIssue({ code: "custom", path: ["secret"], message: "Use a random signing secret of 32–256 letters, digits, underscores or hyphens." });
});

